// Zoomable Bar Chart — Interaction, route: ref
// Source: zoomable-bar-chart
//
// Self-contained: every local import is inlined below. Requires only d3, react.
// Generated by scripts/build-exemplars.mjs — edit src/gallery/, not this file.

import { useEffect, useId, useMemo, useRef } from 'react';
import * as d3 from 'd3';

// ---- inlined from zoomableBar ----
type StationCount = { code: string; count: number };

const LETTERS = 'ABCDEFGHIJKLMNOPQRSTUVWXYZ';

/** mulberry32: a fixed seed keeps the series identical across reloads. */
function seededRandom(seed: number): () => number {
  let state = seed;
  return () => {
    state = (state + 0x6d2b79f5) | 0;
    let t = Math.imul(state ^ (state >>> 15), 1 | state);
    t = (t + Math.imul(t ^ (t >>> 7), 61 | t)) ^ t;
    return ((t ^ (t >>> 14)) >>> 0) / 4294967296;
  };
}

const random = seededRandom(0x5eed1);

/** 96 station codes on a Zipf-like traffic curve, sorted descending like the source notebook. */
const stationTraffic: StationCount[] = Array.from({ length: 96 }, (_, i) => ({
  // The first two letters are a base-26 index, so every code is unique.
  code: LETTERS[Math.floor(i / 26)] + LETTERS[i % 26] + LETTERS[(i * 7 + 3) % 26],
  count: Math.round((42000 / Math.pow(i + 1, 0.55)) * (0.85 + random() * 0.3))
})).sort((a, b) => b.count - a.count);

const MARGIN = { top: 28, right: 12, bottom: 32, left: 56 };
const MIN_LABEL_STEP = 16; // px of band step below which tick labels are dropped

/** One bar per row; `code` is the band label and must be unique. */
export type Data = { code: string; count: number }[];

export default function ZoomableBarChart({
  data = stationTraffic,
  width
}: {
  data?: Data;
  width: number;
}) {
  const svgRef = useRef<SVGSVGElement | null>(null);
  const clipId = `clip${useId().replace(/:/g, '')}`;
  const height = Math.round(width * 0.5);
  const innerWidth = width - MARGIN.left - MARGIN.right;
  const innerHeight = height - MARGIN.top - MARGIN.bottom;

  // The zoom handler mutates this scale's range in place, so it is the one scale the
  // effect rebuilds from rather than treating as immutable.
  const x = useMemo(
    () =>
      d3
        .scaleBand<string>()
        .domain(data.map((d) => d.code))
        .range([MARGIN.left, MARGIN.left + innerWidth])
        .padding(0.1),
    [data, innerWidth]
  );

  const y = useMemo(
    () =>
      d3
        .scaleLinear()
        .domain([0, d3.max(data, (d) => d.count) ?? 0])
        .nice()
        .range([MARGIN.top + innerHeight, MARGIN.top]),
    [data, innerHeight]
  );

  useEffect(() => {
    const node = svgRef.current;
    if (!node || width === 0) return;

    const svg = d3.select(node);
    svg.selectAll('*').remove();
    x.range([MARGIN.left, MARGIN.left + innerWidth]);

    svg
      .append('clipPath')
      .attr('id', clipId)
      .append('rect')
      .attr('x', MARGIN.left)
      .attr('y', MARGIN.top)
      .attr('width', innerWidth)
      .attr('height', innerHeight);

    const bars = svg
      .append('g')
      .attr('clip-path', `url(#${clipId})`)
      .attr('fill', 'var(--accent)')
      .selectAll<SVGRectElement, StationCount>('rect')
      .data(data)
      .join('rect')
      .attr('x', (d) => x(d.code) ?? 0)
      .attr('y', (d) => y(d.count))
      .attr('width', x.bandwidth())
      .attr('height', (d) => y(0) - y(d.count));

    const gx = svg
      .append('g')
      .attr('class', 'axis')
      .attr('transform', `translate(0,${MARGIN.top + innerHeight})`);

    // Labelling all 96 bands overlaps at rest, so thin the ticks to whatever the current
    // band step can hold and let zooming reveal the rest.
    const drawXAxis = () => {
      const every = Math.max(1, Math.ceil(MIN_LABEL_STEP / x.step()));
      gx.call(
        d3
          .axisBottom(x)
          .tickValues(x.domain().filter((_, i) => i % every === 0))
          .tickSizeOuter(0)
      ).call((g) => g.select('.domain').attr('stroke', 'var(--line)'));
    };
    drawXAxis();

    svg
      .append('g')
      .attr('class', 'axis')
      .attr('transform', `translate(${MARGIN.left},0)`)
      .call(d3.axisLeft(y).ticks(5).tickSize(-innerWidth).tickFormat(d3.format('.2s')))
      .call((g) => g.select('.domain').remove())
      .call((g) => g.selectAll('.tick line').attr('class', 'grid'));

    svg
      .append('text')
      .attr('class', 'axis')
      .attr('x', MARGIN.left)
      .attr('y', MARGIN.top - 10)
      .text('Boardings per station. Scroll or drag to zoom the category axis.');

    // Zooming rescales the band range rather than transforming the marks, so bars widen
    // and pan along x while their heights stay fixed. translateExtent pins the pan to the
    // plot box, so the first and last band can never be dragged inside it.
    const zoom = d3
      .zoom<SVGSVGElement, unknown>()
      .scaleExtent([1, 12])
      .extent([
        [MARGIN.left, MARGIN.top],
        [MARGIN.left + innerWidth, MARGIN.top + innerHeight]
      ])
      .translateExtent([
        [MARGIN.left, -Infinity],
        [MARGIN.left + innerWidth, Infinity]
      ])
      .on('zoom', (event: d3.D3ZoomEvent<SVGSVGElement, unknown>) => {
        x.range(
          [MARGIN.left, MARGIN.left + innerWidth].map((d) => event.transform.applyX(d))
        );
        bars.attr('x', (d) => x(d.code) ?? 0).attr('width', x.bandwidth());
        drawXAxis();
      });

    svg.call(zoom);

    return () => {
      svg.on('.zoom', null);
      svg.selectAll('*').remove();
    };
  }, [data, width, height, innerWidth, innerHeight, x, y, clipId]);

  if (width === 0) return null;

  return (
    <svg
      ref={svgRef}
      viewBox={`0 0 ${width} ${height}`}
      width="100%"
      height={height}
      style={{ cursor: 'grab', touchAction: 'none' }}
      role="img"
      aria-label="Zoomable bar chart of boardings across 96 stations"
    />
  );
}
